"use strict";(self.webpackChunk_viben_docs=self.webpackChunk_viben_docs||[]).push([["5514"],{75052(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/viben/zh-Hans/blog/welcome","editUrl":"https://github.com/LinXueyuanStdio/viben/edit/main/apps/docs/blog/2025-02-01-welcome.md","source":"@site/blog/2025-02-01-welcome.md","title":"Viben: Agent Swarm \xd7 Code Evolution","description":"\u6B22\u8FCE\u6765\u5230 Viben \u2014\u2014 \u4E0B\u4E00\u4EE3 Agent Swarm \u4E0E\u4EE3\u7801\u8FDB\u5316\u5E73\u53F0\uFF01","date":"2025-02-01T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/viben/zh-Hans/blog/tags/announcement"},{"inline":true,"label":"agent-swarm","permalink":"/viben/zh-Hans/blog/tags/agent-swarm"},{"inline":true,"label":"code-evolution","permalink":"/viben/zh-Hans/blog/tags/code-evolution"},{"inline":true,"label":"evo","permalink":"/viben/zh-Hans/blog/tags/evo"},{"inline":true,"label":"mcp","permalink":"/viben/zh-Hans/blog/tags/mcp"}],"readingTime":1.45,"hasTruncateMarker":true,"authors":[{"name":"Viben Team","title":"Maintainers","url":"https://github.com/LinXueyuanStdio/viben","imageURL":"https://github.com/LinXueyuanStdio.png","key":"viben-team","page":null}],"frontMatter":{"slug":"welcome","title":"Viben: Agent Swarm \xd7 Code Evolution","authors":["viben-team"],"tags":["announcement","agent-swarm","code-evolution","evo","mcp"]},"unlisted":false},"content":"\u6B22\u8FCE\u6765\u5230 **Viben** \u2014\u2014 \u4E0B\u4E00\u4EE3 Agent Swarm \u4E0E\u4EE3\u7801\u8FDB\u5316\u5E73\u53F0\uFF01\\n\\nViben \u901A\u8FC7\u591A\u667A\u80FD\u4F53\u534F\u4F5C\u548C\u8FED\u4EE3\u4F18\u5316\u9A71\u52A8\u7684\u4EE3\u7801\u8FDB\u5316\uFF0C\u91CD\u65B0\u5B9A\u4E49\u8F6F\u4EF6\u5F00\u53D1\u4F53\u9A8C\u3002\\n\\n{/* truncate */}\\n\\n## \u4EC0\u4E48\u662F Viben\uFF1F\\n\\nViben \u662F\u4E00\u4E2A\u878D\u5408 **Agent Swarm\uFF08\u667A\u80FD\u4F53\u96C6\u7FA4\uFF09** \u4E0E **Code Evolution\uFF08\u4EE3\u7801\u8FDB\u5316\uFF09** \u7406\u5FF5\u7684\u5F00\u53D1\u5E73\u53F0\u3002\u5B83\u4E0D\u4EC5\u4EC5\u662F\u5DE5\u5177\uFF0C\u800C\u662F\u4E00\u5957\u5B8C\u6574\u7684\u667A\u80FD\u5F00\u53D1\u751F\u6001\u7CFB\u7EDF\u3002\\n\\n### \u6838\u5FC3\u7279\u6027\\n\\n#### \u{1F9EC} FileEvo - \u4EE3\u7801\u8FED\u4EE3\u4F18\u5316\\n\\n\u57FA\u4E8E\u542F\u53D1\u5F0F\u8BC4\u4F30\u7684\u4EE3\u7801\u8FDB\u5316\u5F15\u64CE\uFF0C\u901A\u8FC7\u6301\u7EED\u8FED\u4EE3\u8BA9\u4EE3\u7801\u81EA\u6211\u4F18\u5316\uFF1A\\n\\n- \u81EA\u52A8\u5316\u4EE3\u7801\u8D28\u91CF\u8BC4\u4F30\\n- \u667A\u80FD\u91CD\u6784\u5EFA\u8BAE\\n- \u6E10\u8FDB\u5F0F\u6027\u80FD\u4F18\u5316\\n\\n#### \u{1F916} Multi-Agent - \u667A\u80FD\u4F53\u96C6\u7FA4\u7F16\u6392\\n\\n\u591A\u4E2A\u4E13\u4E1A\u667A\u80FD\u4F53\u534F\u540C\u5DE5\u4F5C\uFF0C\u5404\u53F8\u5176\u804C\uFF1A\\n\\n- \u4EE3\u7801\u751F\u6210\u667A\u80FD\u4F53\\n- \u4EE3\u7801\u5BA1\u67E5\u667A\u80FD\u4F53\\n- \u6D4B\u8BD5\u751F\u6210\u667A\u80FD\u4F53\\n- \u6587\u6863\u751F\u6210\u667A\u80FD\u4F53\\n\\n#### \u{1F4CB} Task System - XState \u72B6\u6001\u673A\u9A71\u52A8\\n\\n\u57FA\u4E8E XState \u7684\u4EFB\u52A1\u7BA1\u7406\u7CFB\u7EDF\uFF0C\u8BA9\u5F00\u53D1\u6D41\u7A0B\u53EF\u89C6\u5316\u3001\u53EF\u8FFD\u8E2A\uFF1A\\n\\n- \u4EFB\u52A1\u72B6\u6001\u6D41\u8F6C\uFF1A`backlog \u2192 queue \u2192 in_progress \u2192 review \u2192 completed`\\n- \u5E76\u53D1\u63A7\u5236\u4E0E\u540E\u53F0\u6267\u884C\\n- Gateway \u91CD\u542F\u81EA\u52A8\u6062\u590D\\n\\n#### \u{1F4A1} Idea Generation - \u521B\u610F\u5B75\u5316\\n\\n\u4ECE\u7075\u611F\u5230\u5B9E\u73B0\u7684\u5B8C\u6574\u94FE\u8DEF\uFF1A\\n\\n- \u9700\u6C42\u5206\u6790\u4E0E\u62C6\u89E3\\n- \u6280\u672F\u65B9\u6848\u751F\u6210\\n- \u539F\u578B\u5FEB\u901F\u9A8C\u8BC1\\n\\n#### \u{1F50C} MCP Protocol - \u751F\u6001\u96C6\u6210\\n\\n\u517C\u5BB9 MCP (Model Context Protocol) \u6807\u51C6\uFF0C\u65E0\u7F1D\u5BF9\u63A5\u73B0\u6709 AI \u751F\u6001\uFF1A\\n\\n- \u4E0E Claude \u7B49 MCP \u5BA2\u6237\u7AEF\u6DF1\u5EA6\u96C6\u6210\\n- \u53EF\u6269\u5C55\u7684\u5DE5\u5177\u96C6\\n- \u5F00\u653E\u7684\u534F\u8BAE\u6807\u51C6\\n\\n## \u5F00\u59CB\u4F7F\u7528\\n\\n```bash\\n# \u5B89\u88C5 Viben CLI\\npnpm install -g viben\\n\\n# \u521D\u59CB\u5316\u9879\u76EE\\nviben init\\n\\n# \u542F\u52A8 Gateway\\nviben gateway start\\n```\\n\\n\u67E5\u770B\u6211\u4EEC\u7684[\u6587\u6863](/user/intro)\u4E86\u89E3\u66F4\u591A\uFF01\\n\\n## \u613F\u666F\\n\\n\u6211\u4EEC\u76F8\u4FE1\uFF0C\u672A\u6765\u7684\u8F6F\u4EF6\u5F00\u53D1\u5C06\u7531\u667A\u80FD\u4F53\u96C6\u7FA4\u9A71\u52A8\uFF0C\u4EE3\u7801\u5C06\u50CF\u751F\u547D\u4E00\u6837\u4E0D\u65AD\u8FDB\u5316\u3002Viben \u6B63\u662F\u4E3A\u8FD9\u4E2A\u672A\u6765\u800C\u751F\u3002\\n\\n**Agent Swarm \xd7 Code Evolution** \u2014\u2014 \u8BA9\u4EE3\u7801\u81EA\u5DF1\u8FDB\u5316\u3002"}]}}')}}]);